def report():
    states = {"implemented": "Code vorhanden, Abnahme siehe Hinweis", "partial": "Unvollständig", "missing": "Fehlt", "excluded": "Vom Nutzer ausgeschlossen", "external": "Externer Dienst / Zugang zu prüfen"}
    lines = [REFERENCE, "Kein offener Punkt zählt als fertig.", ""]
    for ident, label, state, remaining in FEATURES:
        lines.append(f"{ident}: {label}\n  {states[state]} · {remaining}")
    return "\n".join(lines)
